INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (NULL, '01AV- MUITO EM BREVE O REI VEM', '01AV- MUITO EM BREVE O REI VEM', 'MUITO EM BREVE O REI VEM,\n(SIM, JESUS VEM!)\nMUITO EM BREVE O REI VEM,\n(SIM, JESUS VEM!) \nMUITO EM BREVE O REI VEM,\nMEU SENHOR JESUS VEM. \n\nVEM DEPRESSA, \nPOIS ELE TE CHAMA. \nTE CONVIDA A PARTICIPAR \nDA FESTA, \nTUDO JÁ ESTÁ PREPARADO, \nMEU SENHOR JESUS VEM.\n\nVEM BUSCAR UM POVO \nPREPARADO, O ESPÍRITO NOS TEM REVELADO, \nVIGIAI, O REI VEM, \nELE VEM.', 'MUITO EM BREVE O REI VEM,\n(SIM, JESUS VEM!)\nMUITO EM BREVE O REI VEM,\n(SIM, JESUS VEM!) \nMUITO EM BREVE O REI VEM,\nMEU SENHOR JESUS VEM. \n\nVEM DEPRESSA, \nPOIS ELE TE CHAMA. \nTE CONVIDA A PARTICIPAR \nDA FESTA, \nTUDO JÁ ESTÁ PREPARADO, \nMEU SENHOR JESUS VEM.\n\nVEM BUSCAR UM POVO \nPREPARADO, O ESPÍRITO NOS TEM REVELADO, \nVIGIAI, O REI VEM, \nELE VEM.', 3, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (NULL, '02AV - PREPARAI-VOS, Ó IGREJA AMADA', '02AV - PREPARAI-VOS, Ó IGREJA AMADA', 'PREPARAI-VOS, \nÓ IGREJA AMADA, \nPOIS O NOIVO \nEM BREVE VIRÁ! \nÓ NOIVA AMADA, ATAVIADA, PREPARADA PARA \nO NOIVO ESTÁ!\n\nCOM ALEGRIA, A PROCLAMAR: \nOH! JESUS, MEU SENHOR, \nVEM NOS BUSCAR! \nA NOIVA PRONTA \nE PREPARADA \nANSEIA ESTAR LOGO \nEM SEU NOVO LAR! \n\nCANDEIA ACESA \nE REVESTIDA, \nAGUARDA PRONTA \nO NOIVO A VIR BUSCAR! \nCOM FÉ SABEMOS \nE VIGIAMOS, \nANSIANDO \nESTE DIA CHEGAR! \n\n\nCOM ALEGRIA A PROCLAMAR: \nOH! JESUS, MEU SENHOR, \nVEM NOS BUSCAR! \nA NOIVA PRONTA \nE PREPARADA \nANSEIA ESTAR LOGO \nEM SEU NOVO LAR!', 'PREPARAI-VOS, \nÓ IGREJA AMADA, \nPOIS O NOIVO \nEM BREVE VIRÁ! \nÓ NOIVA AMADA, ATAVIADA, PREPARADA PARA \nO NOIVO ESTÁ!\n\nCOM ALEGRIA, A PROCLAMAR: \nOH! JESUS, MEU SENHOR, \nVEM NOS BUSCAR! \nA NOIVA PRONTA \nE PREPARADA \nANSEIA ESTAR LOGO \nEM SEU NOVO LAR! \n\nCANDEIA ACESA \nE REVESTIDA, \nAGUARDA PRONTA \nO NOIVO A VIR BUSCAR! \nCOM FÉ SABEMOS \nE VIGIAMOS, \nANSIANDO \nESTE DIA CHEGAR! \n\n\nCOM ALEGRIA A PROCLAMAR: \nOH! JESUS, MEU SENHOR, \nVEM NOS BUSCAR! \nA NOIVA PRONTA \nE PREPARADA \nANSEIA ESTAR LOGO \nEM SEU NOVO LAR!', 3, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (NULL, '03AV- JESUS VOLTARÁ', '03AV- JESUS VOLTARÁ', 'JESUS VOLTARÁ, \nVOU ME PREPARAR,\nQUE DIA GLORIOSO \nQUANDO ELE VOLTAR!\n\nJESUS VOLTARÁ, \nNA GLÓRIA ESTAREI,\nCOM OS ANJOS CANTANDO\nA JESUS LOUVAREI!\n\n\nJESUS REUNIDO \nCOM SUA IGREJA FIEL,\nSERÁ UMA FESTA \nCOM TODOS NO CÉU!\n\nJESUS VOLTARÁ, \nNA GLÓRIA ESTAREI,\nCOM OS ANJOS CANTANDO\nA JESUS LOUVAREI! (3x)', 'JESUS VOLTARÁ, \nVOU ME PREPARAR,\nQUE DIA GLORIOSO \nQUANDO ELE VOLTAR!\n\nJESUS VOLTARÁ, \nNA GLÓRIA ESTAREI,\nCOM OS ANJOS CANTANDO\nA JESUS LOUVAREI!\n\n\nJESUS REUNIDO \nCOM SUA IGREJA FIEL,\nSERÁ UMA FESTA \nCOM TODOS NO CÉU!\n\nJESUS VOLTARÁ, \nNA GLÓRIA ESTAREI,\nCOM OS ANJOS CANTANDO\nA JESUS LOUVAREI! <bis tipo=''3''>', 3, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (NULL, '04AV- AS PARÁBOLAS DO REINO', '04AV- AS PARÁBOLAS DO REINO', 'SAINDO DE CASA \nNAQUELE DIA, \nASSENTADO JUNTO AO MAR, JESUS FOI EXPLICAR\n\nÀQUELA MULTIDĀO \nE A TODOS QUE O SEGUIAM,\nSOBRE AS PARÁBOLAS \nDE UM REINO QUE VIRIA.\n\nSETE SÃO \nAS PARÁBOLAS DO REINO:\nSEMEADOR, TRIGO E JOIO,\n\nGRÃO DE MOSTARDA, FERMENTO,\n\nTESOURO ESCONDIDO, PÉROLA E REDE.\n\nVAMOS VIGIAR E ORAR,\nJESUS BREVE VIRÁ; IREMOS TODOS COM \nELE MORAR. \nMARANATA, JESUS VEM!', 'SAINDO DE CASA \nNAQUELE DIA, \nASSENTADO JUNTO AO MAR, JESUS FOI EXPLICAR\n\nÀQUELA MULTIDĀO \nE A TODOS QUE O SEGUIAM,\nSOBRE AS PARÁBOLAS \nDE UM REINO QUE VIRIA.\n\nSETE SÃO \nAS PARÁBOLAS DO REINO:\nSEMEADOR, TRIGO E JOIO,\n\nGRÃO DE MOSTARDA, FERMENTO,\n\nTESOURO ESCONDIDO, PÉROLA E REDE.\n\nVAMOS VIGIAR E ORAR,\nJESUS BREVE VIRÁ; IREMOS TODOS COM \nELE MORAR. \nMARANATA, JESUS VEM!', 3, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (NULL, '05AV- EU CLAMO, EU ORO', '05AV- EU CLAMO, EU ORO', 'EU CLAMO, EU ORO \nPELO SANGUE LÁ DA CRUZ,\nEU CLAMO, EU ORO \nPELO ESPÍRITO QUE RELUZ.\n\n\nQUANDO EU OLHO \nPARA A CRUZ,\nSEI QUE A VITÓRIA CHEGARÁ,\nPOIS POR MIM \nMORREU JESUS\nQUE NÃO ME ABANDONA \nNEM ME ABANDONARÁ.\n\nEU CLAMO, EU ORO \nPELO SANGUE \nLÁ DA CRUZ,\nEU CLAMO, EU ORO \nPELO ESPÍRITO \nQUE RELUZ.', 'EU CLAMO, EU ORO \nPELO SANGUE LÁ DA CRUZ,\nEU CLAMO, EU ORO \nPELO ESPÍRITO QUE RELUZ.\n\n\nQUANDO EU OLHO \nPARA A CRUZ,\nSEI QUE A VITÓRIA CHEGARÁ,\nPOIS POR MIM \nMORREU JESUS\nQUE NÃO ME ABANDONA \nNEM ME ABANDONARÁ.\n\nEU CLAMO, EU ORO \nPELO SANGUE \nLÁ DA CRUZ,\nEU CLAMO, EU ORO \nPELO ESPÍRITO \nQUE RELUZ.', 3, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (NULL, '06AV- A VITÓRIA DA IGREJA', '06AV- A VITÓRIA DA IGREJA', 'NA BATALHA EU ORO \nAO SENHOR,\nNA BATALHA EU SUPLICO \nSEU FAVOR\n\nE DE JOELHOS EU SOU \nMAIS QUE VENCEDOR,\nGLORIFICO A DEUS \nQUE ATENDE \nAO MEU CLAMOR.\n\nBATALHA, \nORAÇÃO, VITÓRIA, \nGLÓRIA A JESUS, \n\nGLORIFICO A DEUS \nQUE ATENDE \nAO MEU CLAMOR.\n\n3X\n\nNA BATALHA EU ORO \nAO SENHOR,\nNA BATALHA EU SUPLICO \nSEU FAVOR\n\nE DE JOELHOS EU SOU \nMAIS QUE VENCEDOR,\nGLORIFICO A DEUS \nQUE ATENDE \nAO MEU CLAMOR.\n\nBATALHA, \nORAÇÃO, VITÓRIA, \nGLÓRIA A JESUS, \n\nGLORIFICO A DEUS \nQUE ATENDE \nAO MEU CLAMOR.\n\n3X', 'NA BATALHA EU ORO \nAO SENHOR,\nNA BATALHA EU SUPLICO \nSEU FAVOR\n\nE DE JOELHOS EU SOU \nMAIS QUE VENCEDOR,\nGLORIFICO A DEUS \nQUE ATENDE \nAO MEU CLAMOR.\n\nBATALHA, \nORAÇÃO, VITÓRIA, \nGLÓRIA A JESUS, \n\nGLORIFICO A DEUS \nQUE ATENDE \nAO MEU CLAMOR.\n\n<bis tipo=''3''>\n\nNA BATALHA EU ORO \nAO SENHOR,\nNA BATALHA EU SUPLICO \nSEU FAVOR\n\nE DE JOELHOS EU SOU \nMAIS QUE VENCEDOR,\nGLORIFICO A DEUS \nQUE ATENDE \nAO MEU CLAMOR.\n\nBATALHA, \nORAÇÃO, VITÓRIA, \nGLÓRIA A JESUS, \n\nGLORIFICO A DEUS \nQUE ATENDE \nAO MEU CLAMOR.\n\n<bis tipo=''3''>', 3, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (NULL, '07AV- ESTÁ CHEGANDO A HORA', '07AV- ESTÁ CHEGANDO A HORA', 'ESTÁ CHEGANDO A HORA,\nO TREM JÁ VAI PARTIR\nLEVANDO OS \nCORDEIRINHOS\nQUE VÃO AO CÉU SUBIR.\n\nJESUS ESTÁ CHAMANDO,\nA TODOS CONVIDANDO:\n''VENHAM SEM DEMORA\nPRA NOVA JERUSALÉM''.\n\nVOCÊ, Ó PEQUENINO,\nPOR QUE NÃO \nVEM TAMBÉM?\nRECEBA O SEU BILHETE\nE ENTRE NESSE TREM.\n\nE ALI JUNTOS ESTAREMOS\nNA CELESTIAL CIDADE,\nCOM CRISTO ANDAREMOS,\nSERÁ SÓ FELICIDADE.', 'ESTÁ CHEGANDO A HORA,\nO TREM JÁ VAI PARTIR\nLEVANDO OS \nCORDEIRINHOS\nQUE VÃO AO CÉU SUBIR.\n\nJESUS ESTÁ CHAMANDO,\nA TODOS CONVIDANDO:\n''VENHAM SEM DEMORA\nPRA NOVA JERUSALÉM''.\n\nVOCÊ, Ó PEQUENINO,\nPOR QUE NÃO \nVEM TAMBÉM?\nRECEBA O SEU BILHETE\nE ENTRE NESSE TREM.\n\nE ALI JUNTOS ESTAREMOS\nNA CELESTIAL CIDADE,\nCOM CRISTO ANDAREMOS,\nSERÁ SÓ FELICIDADE.', 3, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
